const { readdirSync, lstatSync, mkdirSync, copyFileSync } = await import('fs');
const { dirname, join } = await import('path');
function copyDir(src, dest, options = {}) {
  const copy = (sourceDir, destinationDir, relativeDir) => {
    for (const entry of readdirSync(sourceDir)) {
      const source = join(sourceDir, entry);
      const entryRelativePath = relativeDir ? join(relativeDir, entry) : entry;
      if (options.filter && !options.filter(source, entryRelativePath)) continue;
      const stat = lstatSync(source);
      if (stat.isSymbolicLink()) {
        options.onSkip?.(entryRelativePath, 'symlink');
        continue;
      }
      const destination = join(destinationDir, entry);
      if (stat.isDirectory()) {
        if (!options.dryRun) mkdirSync(destination, { recursive: true });
        copy(source, destination, entryRelativePath);
      } else {
        if (options.dryRun) { console.log('copy', entryRelativePath); }
        else { mkdirSync(dirname(destination), { recursive: true }); copyFileSync(source, destination); }
      }
    }
  };
  copy(src, dest, '');
}
const warns = [];
copyDir('/tmp/w2src/assets', '/tmp/w2dst/assets', { onSkip: (rel, reason) => warns.push(rel + ':' + reason) });
console.log('skipped:', JSON.stringify(warns));
for (const f of readdirSync('/tmp/w2dst/assets/sub')) console.log(' -', f);
"
